   460	void GfxFont::readFontDescriptor(XRef *xref, Dict *fontDict) {
   461	  double t;
   462	
   463	  // assume Times-Roman by default (for substitution purposes)
   464	  flags = fontSerif;
   465	
   466	  missingWidth = 0;
   467	
   468	  Object obj1 = fontDict->lookup("FontDescriptor");
   469	  if (obj1.isDict()) {
   470	
   471	    // get flags
   472	    Object obj2 = obj1.dictLookup("Flags");
   473	    if (obj2.isInt()) {
   474	      flags = obj2.getInt();
   475	    }
   476	
   477	    // get name
   478	    obj2 = obj1.dictLookup("FontName");
   479	    if (obj2.isName()) {
   480	      embFontName = new GooString(obj2.getName());
   481	    }
   482	    if (embFontName == nullptr) {
   483	      // get name with typo
   484	      obj2 = obj1.dictLookup("Fontname");
   485	      if (obj2.isName()) {
   486	        embFontName = new GooString(obj2.getName());
   487	        error(errSyntaxWarning, -1, "The file uses Fontname instead of FontName please notify the creator that the file is broken");
   488	      }
   489	    }
   490	
   491	    // get family
   492	    obj2 = obj1.dictLookup("FontFamily");
   493	    if (obj2.isString()) family = new GooString(obj2.getString());
   494	
   495	    // get stretch
   496	    obj2 = obj1.dictLookup("FontStretch");
   497	    if (obj2.isName()) {
   498	      if (strcmp(obj2.getName(), "UltraCondensed") == 0) stretch = UltraCondensed;
   499	      else if (strcmp(obj2.getName(), "ExtraCondensed") == 0) stretch = ExtraCondensed;
   500	      else if (strcmp(obj2.getName(), "Condensed") == 0) stretch = Condensed;
   501	      else if (strcmp(obj2.getName(), "SemiCondensed") == 0) stretch = SemiCondensed;
   502	      else if (strcmp(obj2.getName(), "Normal") == 0) stretch = Normal;
   503	      else if (strcmp(obj2.getName(), "SemiExpanded") == 0) stretch = SemiExpanded;
   504	      else if (strcmp(obj2.getName(), "Expanded") == 0) stretch = Expanded;
   505	      else if (strcmp(obj2.getName(), "ExtraExpanded") == 0) stretch = ExtraExpanded;
   506	      else if (strcmp(obj2.getName(), "UltraExpanded") == 0) stretch = UltraExpanded;
   507	      else error(errSyntaxWarning, -1, "Invalid Font Stretch");
   508	    }
   509	    
   510	    // get weight
   511	    obj2 = obj1.dictLookup("FontWeight");
   512	    if (obj2.isNum()) {
   513	      if (obj2.getNum() == 100) weight = W100;
   514	      else if (obj2.getNum() == 200) weight = W200;
   515	      else if (obj2.getNum() == 300) weight = W300;
   516	      else if (obj2.getNum() == 400) weight = W400;
   517	      else if (obj2.getNum() == 500) weight = W500;
   518	      else if (obj2.getNum() == 600) weight = W600;
   519	      else if (obj2.getNum() == 700) weight = W700;
   520	      else if (obj2.getNum() == 800) weight = W800;
   521	      else if (obj2.getNum() == 900) weight = W900;
   522	      else error(errSyntaxWarning, -1, "Invalid Font Weight");
   523	    }
   524	
   525	    // look for MissingWidth
   526	    obj2 = obj1.dictLookup("MissingWidth");
   527	    if (obj2.isNum()) {
   528	      missingWidth = obj2.getNum();
   529	    }
   530	
   531	    // get Ascent and Descent
   532	    obj2 = obj1.dictLookup("Ascent");
   533	    if (obj2.isNum()) {
   534	      t = 0.001 * obj2.getNum();
   535	      // some broken font descriptors specify a negative ascent
   536	      if (t < 0) {
   537	        t = -t;
   538	      }
   539	      // some broken font descriptors set ascent and descent to 0;
   540	      // others set it to ridiculous values (e.g., 32768)
   541	      if (t != 0 && t < 3) {
   542	        ascent = t;
   543	      }
   544	    }
   545	    obj2 = obj1.dictLookup("Descent");
   546	    if (obj2.isNum()) {
   547	      t = 0.001 * obj2.getNum();
   548	      // some broken font descriptors specify a positive descent
   549	      if (t > 0) {
   550	        t = -t;
   551	      }
   552	      // some broken font descriptors set ascent and descent to 0
   553	      if (t != 0 && t > -3) {
   554	        descent = t;
   555	      }
   556	    }
   557	
   558	    // font FontBBox
   559	    obj2 = obj1.dictLookup("FontBBox");
   560	    if (obj2.isArray()) {
   561	      for (int i = 0; i < 4 && i < obj2.arrayGetLength(); ++i) {
   562	        Object obj3 = obj2.arrayGet(i);
   563	        if (obj3.isNum()) {
   564	          fontBBox[i] = 0.001 * obj3.getNum();
   565	        }
   566	      }
   567	    }
